class DecompressHandler extends DecoratorHandler {
  /** @type {Transform[]} */
  #decompressors = []
  /**
   * Last stream of the chain, the one decoded output is pulled from. Held
   * separately from #decompressors so the pump keeps working while completion
   * waits for the consumer.
   * @type {Transform|null}
   */
  #output = null
  /** @type {Record<string, string | string[]> | undefined} */
  #trailers
  /** @type {Readonly<number[]>} */
  #skipStatusCodes
  /** @type {boolean} */
  #skipErrorResponses
  /** @type {number} */
  #maxSize
  /** @type {number} */
  #decompressedSize = 0
  /** @type {boolean} */
  #terminated = false
  /** @type {boolean} */
  #inputEnded = false
  /**
   * The transport is paused for two reasons that must stay apart: the consumer
   * asking us to stop pushing decoded output, and the decoder's writable side
   * filling up. One flag for both would let a decoder drain resume a
   * consumer-paused body, and a consumer resume restart the transport while the
   * decoder is still backed up.
   * @type {boolean}
   */
  #consumerPaused = false
  /** @type {boolean} */
  #writeBlocked = false
  /** @type {boolean} */
  #outputEnded = false
  /** @type {boolean} */
  #pumping = false
  /**
   * Controller of the connection currently carrying the response.
   * @type {Controller|null}
   */
  #controller = null
  /** @type {Controller} */
  #controllerProxy

  constructor (handler, { skipStatusCodes = defaultSkipStatusCodes, skipErrorResponses = true, maxSize = defaultMaxSize } = {}) {
    if (!Number.isSafeInteger(maxSize) || maxSize < 0) {
      throw new InvalidArgumentError('maxSize must be a non-negative integer')
    }

    super(handler)
    this.#skipStatusCodes = skipStatusCodes
    this.#skipErrorResponses = skipErrorResponses
    this.#maxSize = maxSize
    this.#controllerProxy = this.#createControllerProxy()
  }

  /**
   * The controller handed to the downstream handler. It records the consumer's
   * own pause reason instead of passing it straight to the transport, so the
   * decoder's writable pressure and the consumer's demand can pause the
   * transport independently. Its resume also re-pumps decoded output: a pump
   * stopped mid-stream leaves data inside the decoder that no further
   * 'readable' event would announce.
   * @returns {Controller}
   */
  #createControllerProxy () {
    const handler = this

    return {
      pause () {
        handler.#consumerPaused = true
        handler.#controller?.pause()
      },

      resume () {
        handler.#consumerPaused = false
        handler.#pump()
        handler.#resumeTransport()
      },

      abort (reason) {
        handler.#controller?.abort(reason)
      },

      get paused () { return handler.#consumerPaused },
      get aborted () { return handler.#controller?.aborted ?? false },
      get reason () { return handler.#controller?.reason ?? null },

      get rawHeaders () { return handler.#controller?.rawHeaders ?? null },
      set rawHeaders (value) {
        if (handler.#controller) {
          handler.#controller.rawHeaders = value
        }
      },

      get rawTrailers () { return handler.#controller?.rawTrailers ?? null },
      set rawTrailers (value) {
        if (handler.#controller) {
          handler.#controller.rawTrailers = value
        }
      }
    }
  }

  /**
   * Tracks the controller of the connection the response is arriving on.
   * @param {Controller} controller
   * @returns {void}
   */
  #setController (controller) {
    if (controller == null || controller === this.#controller) {
      return
    }

    this.#controller = controller

    // A retry or a resumed download runs on another connection whose controller
    // starts unpaused. Re-apply the reasons that still hold here, so a later
    // drain or consumer resume acts on this connection rather than resuming the
    // one we already left behind.
    if (this.#consumerPaused || this.#writeBlocked) {
      controller.pause()
    }
  }

  /**
   * Resumes the transport once no pause reason holds anymore.
   * @returns {void}
   */
  #resumeTransport () {
    if (this.#consumerPaused || this.#writeBlocked) {
      return
    }

    this.#controller?.resume()
  }

