/**
 * Stops decompression and reports an error.
 * @param {Error} error - The decompression error
 * @returns {void}
 */
#fail (error) {
  if (this.#terminated) {
    return
  }

  if (this.#inputEnded) {
    // The request is already marked complete once the compressed input ends,
    // so controller.abort() can no longer propagate decoder flush errors.
    this.onResponseError(this.#controller, error)
  } else {
    this.#controller.abort(error)
  }
}

/**
 * Pulls decoded output and pushes it downstream for as long as the consumer
 * keeps asking for more. Once it pauses we stop reading, so the output stays
 * inside the decoder, whose writable side then backs up into the transport
 * instead of being buffered here.
 * @returns {void}
 */
#pump () {
  if (this.#terminated || this.#pumping || this.#output === null) {
    return
  }

  this.#pumping = true
  try {
    let chunk
    while (!this.#consumerPaused && (chunk = this.#output.read()) !== null) {
      if (this.#maxSize !== 0) {
        const decompressedSize = this.#decompressedSize + chunk.length
        if (decompressedSize > this.#maxSize) {
          this.#fail(new ResponseExceededMaxSizeError(
            `Decompressed response size (${decompressedSize}) exceeded maxSize (${this.#maxSize})`
          ))
          return
        }

        this.#decompressedSize = decompressedSize
      }

      if (super.onResponseData(this.#controllerProxy, chunk) === false) {
        // A consumer may signal backpressure by return value instead of
        // pausing the controller; either way it resumes through the same one.
        this.#consumerPaused = true
      }
    }
  } finally {
    this.#pumping = false
  }

  if (this.#consumerPaused) {
    this.#controller?.pause()
    return
  }

  this.#finishIfEnded()
}

/**
 * Completes the response, once the decoder is done and the consumer has taken
 * everything it produced.
 * @returns {void}
 */
#finishIfEnded () {
  if (this.#terminated || !this.#outputEnded || this.#consumerPaused) {
    return
  }

  this.#terminated = true
  this.#cleanupDecompressors()
  super.onResponseEnd(this.#controllerProxy, this.#trailers)
}

/**
 * Sets up event handlers for a decompressor stream using readable events
 * @param {DecompressorStream} decompressor - The decompressor stream
 * @returns {void}
 */
#setupDecompressorEvents (decompressor) {
  this.#output = decompressor

  decompressor.on('readable', () => {
    this.#pump()
  })

  decompressor.on('error', (error) => {
    this.#fail(error)
  })
}

/**
 * Makes the decoder's writable pressure visible to the transport.
 * @returns {void}
 */
#setupInputEvents () {
  this.#decompressors[0].on('drain', () => {
    this.#writeBlocked = false
    this.#resumeTransport()
  })
}

/**
 * Sets up event handling for a single decompressor
 * @returns {void}
 */
#setupSingleDecompressor () {
  const decompressor = this.#decompressors[0]
  this.#setupDecompressorEvents(decompressor)
  this.#setupInputEvents()

  decompressor.on('end', () => {
    if (this.#terminated) {
      return
    }

    this.#outputEnded = true
    // A consumer that paused on the last chunk has not seen all of the body
    // yet; its resume finishes the response.
    this.#finishIfEnded()
  })
}

/**
 * Sets up event handling for multiple chained decompressors using pipeline
 * @returns {void}
 */
#setupMultipleDecompressors () {
  this.#setupDecompressorEvents(this.#decompressors[this.#decompressors.length - 1])
  this.#setupInputEvents()

  pipeline(this.#decompressors, (err) => {
    if (this.#terminated) {
      return
    }

    if (err) {
      this.#fail(err)
      return
    }

    this.#outputEnded = true
    this.#finishIfEnded()
  })
}

/**
 * Cleans up decompressor references to prevent memory leaks
 * @returns {void}
 */
#cleanupDecompressors () {
  this.#decompressors.length = 0
  this.#output = null
}

