          if (decompressedSize > this.#maxSize) {
            this.#fail(new ResponseExceededMaxSizeError(
              `Decompressed response size (${decompressedSize}) exceeded maxSize (${this.#maxSize})`
            ))
            return
          }

          this.#decompressedSize = decompressedSize
        }

