   * Pulls decoded output and pushes it downstream for as long as the consumer
   * keeps asking for more. Once it pauses we stop reading, so the output stays
   * inside the decoder, whose writable side then backs up into the transport
   * instead of being buffered here.
   * @returns {void}
   */
  #pump () {
    if (this.#terminated || this.#pumping || this.#output === null) {
      return
    }

    this.#pumping = true
    try {
