        handler.#controller?.abort(reason)
      },

      get paused () { return handler.#consumerPaused },
      get aborted () { return handler.#controller?.aborted ?? false },
      get reason () { return handler.#controller?.reason ?? null },

      get rawHeaders () { return handler.#controller?.rawHeaders ?? null },
      set rawHeaders (value) {
        if (handler.#controller) {
          handler.#controller.rawHeaders = value
        }
      },

      get rawTrailers () { return handler.#controller?.rawTrailers ?? null },
      set rawTrailers (value) {
        if (handler.#controller) {
          handler.#controller.rawTrailers = value
        }
      }
    }
  }

  /**
   * Tracks the controller of the connection the response is arriving on.
   * @param {Controller} controller
   * @returns {void}
   */
  #setController (controller) {
    if (controller == null || controller === this.#controller) {
      return
    }

    this.#controller = controller

    // A retry or a resumed download runs on another connection whose controller
    // starts unpaused. Re-apply the reasons that still hold here, so a later
    // drain or consumer resume acts on this connection rather than resuming the
    // one we already left behind.
    if (this.#consumerPaused || this.#writeBlocked) {
      controller.pause()
    }
  }

  /**
   * Resumes the transport once no pause reason holds anymore.
   * @returns {void}
   */
  #resumeTransport () {
    if (this.#consumerPaused || this.#writeBlocked) {
      return
    }

    this.#controller?.resume()
  }

  /**
   * Determines if decompression should be skipped based on encoding and status code
   * @param {string} contentEncoding - Content-Encoding header value
   * @param {number} statusCode - HTTP status code of the response
   * @returns {boolean} - True if decompression should be skipped
   */
  #shouldSkipDecompression (contentEncoding, statusCode) {
