  t = tspl(t, { plan: 2 })

  // Comfortably past the 64 MiB limit the interceptor used to impose, and
  // consumed as a stream so it is never held in memory all at once.
  const chunk = Buffer.alloc(1024 * 1024, 'a')
  const chunks = 96
  const server = createServer({ joinDuplicateHeaders: true }, (_req, res) => {
    res.writeHead(200, {
      'Content-Encoding': 'gzip'
    })

    const gzip = createGzip()
    gzip.pipe(res)
    for (let i = 0; i < chunks; i++) {
      gzip.write(chunk)
    }
    gzip.end()
  })

