test('should stop decoding while the consumer is paused', async t => {
  t = tspl(t, { plan: 4 })

  const chunk = Buffer.alloc(512 * 1024, 'a')
  const chunks = 16
  const total = chunk.length * chunks
  const server = createServer({ joinDuplicateHeaders: true }, (_req, res) => {
    res.writeHead(200, {
      'Content-Encoding': 'gzip'
    })

    const gzip = createGzip()
    gzip.pipe(res)
    for (let i = 0; i < chunks; i++) {
      gzip.write(chunk)
    }
    gzip.end()
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(interceptors.decompress())

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  let controller
  let received = 0
  let ended = false
  let paused = false
  let receivedWhilePaused = 0

  const handler = {
    onRequestStart (ctrl) {
      controller = ctrl
    },

    onResponseStart () {},

    onResponseData (_ctrl, data) {
      received += data.length

      if (paused) {
        receivedWhilePaused += data.length
        return
      }

      // Hold the body for a macrotask. Nothing more may be decoded until the
      // resume below, no matter how much compressed input keeps arriving.
      paused = true
      controller.pause()
      setTimeout(() => {
        paused = false
        controller.resume()
      }, 50)
    },

    onResponseEnd () {
      ended = true
      t.equal(receivedWhilePaused, 0, 'no data delivered while paused')
      t.equal(received, total, 'all data received')
    },

    onResponseError (_ctrl, err) {
      t.fail(err)
    }
  }

  await client.dispatch({ method: 'GET', path: '/' }, handler)

  t.ok(!ended, 'the response cannot have ended before the consumer resumed')

  await once(client, 'disconnect').catch(() => {})
  while (!ended) {
    await new Promise(resolve => setTimeout(resolve, 10))
  }

  t.ok(ended, 'the response ends once the consumer drains it')

  await t.completed
})

test('should delay completion until a consumer paused on the last chunk resumes', async t => {
  t = tspl(t, { plan: 3 })

  const data = 'the whole body arrives in one decoded chunk'
  const server = createServer({ joinDuplicateHeaders: true }, (_req, res) => {
    res.writeHead(200, {
      'Content-Encoding': 'gzip'
    })
    res.end(gzipSync(data))
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(interceptors.decompress())

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  let controller
  let resumed = false
  let body = ''
  const completed = new Promise(resolve => {
    const handler = {
      onRequestStart (ctrl) {
        controller = ctrl
      },

      onResponseStart () {},

      onResponseData (_ctrl, chunk) {
        body += chunk.toString()
        controller.pause()
        setTimeout(() => {
          resumed = true
          controller.resume()
        }, 50)
      },

      onResponseEnd () {
        t.ok(resumed, 'completion waits for the consumer to resume')
        t.equal(body, data)
        resolve()
      },

      onResponseError (_ctrl, err) {
        t.fail(err)
      }
    }

    client.dispatch({ method: 'GET', path: '/' }, handler)
  })

  await completed

  t.ok(resumed)

  await t.completed
})

